import{_ as n,q as a,s,J as t}from"./framework-4ff91fa4.js";const e={},p=t(`<h2 id="可空类型" tabindex="-1"><a class="header-anchor" href="#可空类型" aria-hidden="true">#</a> 可空类型</h2><p><code>String</code> 不能存 null；<code>String?</code> 可以。访问可空对象前，要检查或明确处理缺失值。</p><div class="language-kotlin line-numbers-mode" data-ext="kt"><pre class="language-kotlin"><code><span class="token keyword">fun</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">val</span> nickname<span class="token operator">:</span> String<span class="token operator">?</span> <span class="token operator">=</span> <span class="token keyword">null</span>
    <span class="token function">println</span><span class="token punctuation">(</span>nickname<span class="token operator">?</span><span class="token punctuation">.</span>length<span class="token punctuation">)</span>       <span class="token comment">// null</span>
    <span class="token function">println</span><span class="token punctuation">(</span>nickname <span class="token operator">?:</span> <span class="token string-literal singleline"><span class="token string">&quot;匿名用户&quot;</span></span><span class="token punctuation">)</span> <span class="token comment">// 匿名用户</span>
    <span class="token keyword">val</span> length <span class="token operator">=</span> nickname<span class="token operator">?</span><span class="token punctuation">.</span>length <span class="token operator">?:</span> <span class="token number">0</span>
    <span class="token function">println</span><span class="token punctuation">(</span>length<span class="token punctuation">)</span>                <span class="token comment">// 0</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>安全调用 <code>?.</code> 在接收者为 null 时跳过调用并返回 null。Elvis 运算符 <code>?:</code> 在左侧为空时才求值右侧，可以用来给默认值，或提前 return / throw。</p><h2 id="提前返回与智能转换" tabindex="-1"><a class="header-anchor" href="#提前返回与智能转换" aria-hidden="true">#</a> 提前返回与智能转换</h2><div class="language-kotlin line-numbers-mode" data-ext="kt"><pre class="language-kotlin"><code><span class="token keyword">fun</span> <span class="token function">greet</span><span class="token punctuation">(</span>name<span class="token operator">:</span> String<span class="token operator">?</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">val</span> validName <span class="token operator">=</span> name<span class="token operator">?</span><span class="token punctuation">.</span><span class="token function">trim</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">?</span><span class="token punctuation">.</span><span class="token function">takeIf</span> <span class="token punctuation">{</span> it<span class="token punctuation">.</span><span class="token function">isNotEmpty</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">}</span> <span class="token operator">?:</span> <span class="token keyword">return</span>
    <span class="token function">println</span><span class="token punctuation">(</span><span class="token string-literal singleline"><span class="token string">&quot;你好，</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">$</span><span class="token expression">validName</span></span><span class="token string">&quot;</span></span><span class="token punctuation">)</span>
<span class="token punctuation">}</span>
<span class="token keyword">fun</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token function">greet</span><span class="token punctuation">(</span><span class="token keyword">null</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token function">greet</span><span class="token punctuation">(</span><span class="token string-literal singleline"><span class="token string">&quot; 小林 &quot;</span></span><span class="token punctuation">)</span> <span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>也可以在稳定的局部变量上先写 <code>if (name == null) return</code>，后面通常就能按非空类型使用它。可变属性、自定义 getter 或被闭包修改的变量未必能智能转换，需要先保存到局部 val。</p><h2 id="为什么慎用" tabindex="-1"><a class="header-anchor" href="#为什么慎用" aria-hidden="true">#</a> 为什么慎用 !!</h2><p><code>value!!</code> 告诉编译器直接把它当作非空，实际为 null 会抛出空指针异常。它不是“解决空安全”的通用方式。对于必须存在的输入，使用 <code>requireNotNull</code> 并写清错误原因；对于允许缺失的数据，显式保留可空语义。</p><h2 id="动手练习" tabindex="-1"><a class="header-anchor" href="#动手练习" aria-hidden="true">#</a> 动手练习</h2><p>将可空输入转为整数，解析失败或缺失时返回 0。</p><details><summary>查看参考思路</summary><p>val number = input?.toIntOrNull() ?: 0。</p></details><h2 id="延伸阅读" tabindex="-1"><a class="header-anchor" href="#延伸阅读" aria-hidden="true">#</a> 延伸阅读</h2><p><a href="https://kotlinlang.org/docs/null-safety.html" target="_blank" rel="noopener noreferrer">Kotlin 官方文档：null-safety</a>。本章为原创中文学习笔记，示例以 Kotlin/JVM 为主；使用扩展库的章节需先配置依赖。</p>`,14),o=[p];function l(c,i){return a(),s("div",null,o)}const r=n(e,[["render",l],["__file","null-safety.html.vue"]]);export{r as default};
